#include "stdlib/stats/base/dists/negative-binomial/pmf.h"
#include "stdlib/math/base/special/ceil.h"
#include <stdlib.h>
#include <stdio.h>

static double random_uniform( const double min, const double max ) {
	double v = (double)rand() / ( (double)RAND_MAX + 1.0 );
	return min + ( v * (max - min) );
}

int main( void ) {
	double x;
	double r;
	double p;
	double y;
	int i;

	for ( i = 0; i < 25; i++ ) {
		x = stdlib_base_ceil( random_uniform( 0.0, 40.0 ) );
		r = stdlib_base_ceil( random_uniform( 1.0, 40.0 ) );
		p = random_uniform( 0.01, 1.0 );
		y = stdlib_base_dists_negative_binomial_pmf( x, r, p );
		printf( "x: %lf, r: %lf, p: %lf, P(X=x;r,p): %lf\n", x, r, p, y );
	}
}
